A 'plan-frozen-counts' (@($plan.lanes).Count-eq3-and[int]$plan.totals.measuredWaves-eq128-and[int]$plan.totals.measuredBlockProcesses-eq384-and[int]$plan.totals.measuredSamples-eq1152-and[int]$plan.totals.warmupProcesses-eq12-and[int]$plan.licensing.stressWaves-eq172-and[int]$plan.licensing.stressFreshUnityProcesses-eq516) '3 lanes / 128 waves / 384 blocks / 1152 samples / 172 stress waves'
