$expanded=foreach($row in @($schedule.rows)){$algs=@(Get-G13R48WilliamsRow -Algorithms @($row.algorithms) -Block ([int]$row.block));for($i=0;$i-lt$algs.Count;$i++){[pscustomobject]@{campaignId=$row.campaignId;lane=[int]$row.lane;admissionPosition=[int]$row.admissionPosition;algorithm=$algs[$i];position=$i+1;predecessor=if($i){$algs[$i-1]}else{'NONE'}}}}
$balance=$true;foreach($g in @($schedule.rows|Group-Object campaignId,lane)){if($g.Count-notin@(10,11)){$balance=$false}};foreach($g in @($schedule.rows|Group-Object lane,admissionPosition)){$laneNumber=[int]$g.Group[0].lane;$counts=@($schedule.rows|Where-Object lane -eq $laneNumber|Group-Object admissionPosition|ForEach-Object Count);if((($counts|Measure-Object -Maximum).Maximum-($counts|Measure-Object -Minimum).Minimum)-gt1){$balance=$false}};A 'three-lane-balance' $balance 'campaign/lane 10-11 and admission imbalance <=1'
$negative=@($regenerated|Select-Object -Skip 1);A 'negative-incomplete-schedule-fails' ((Test-G13R48Schedule $negative).passed-eq$false) 'one row removed'
