$stressText=[IO.File]::ReadAllText((Join-Path $ProjectPath 'Research\Verification\Run-Gate13R48h3LaneLicensingStressV1.ps1'));$pilotText=[IO.File]::ReadAllText((Join-Path $ProjectPath 'Research\Run-Gate13R48h3LanePilotV1.ps1'));$analysisText=[IO.File]::ReadAllText((Join-Path $ProjectPath 'Research\Analyze-Gate13R48h3LanePilotV1.ps1'));A 'process-identity-is-pid-plus-start' ($stressText.Contains("processIdentityRule='pid-at-os-process-start-time-utc-v1'")-and$pilotText.Contains("processIdentityRule='pid-at-os-process-start-time-utc-v1'")-and$analysisText.Contains('processIdentity=([string]$manifest.processId')) 'PID reuse is allowed only when OS process start time differs'
